window.CFA_LESSONS=(window.CFA_LESSONS||[]).concat([{"module_id":"CFA26-10-01","title":"Ethics and Trust in the Investment Profession","version":"2026","source_basis":[{"source_id":"CFAI_2026","pdf_pages":[17,46],"relation":"primary"},{"source_id":"Kaplan_2026","pdf_pages":[154,160],"relation":"supplementary"},{"source_id":"SAPP_2026","pdf_pages":[4,14],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-10-01-LOS01","learning_goal_vi":"Giải thích ethics và phân biệt đạo đức, quy tắc ứng xử, các nhóm stakeholders.","status":"targeted_CFAI_Kaplan_SAPP_and_scenario_QA_pass","competency_criteria":["Phù hợp động từ và LOS CFAI 2026","Đối chiếu với Kaplan/SAPP cùng chủ đề","Có 4+ phần lý thuyết tiếng Việt và 2 ví dụ tình huống","3 câu hỏi tự biên soạn có giải thích lựa chọn"],"concept_ids":["S01-01","S01-02","S01-03","S01-04"],"formula_ids":["F01-01"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":19},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":154},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":5}},"missing_items":[]},{"los_id":"CFA26-10-01-LOS02","learning_goal_vi":"Mô tả vai trò của code of ethics trong việc xác định một profession.","status":"targeted_CFAI_Kaplan_SAPP_and_scenario_QA_pass","competency_criteria":["Phù hợp động từ và LOS CFAI 2026","Đối chiếu với Kaplan/SAPP cùng chủ đề","Có 4+ phần lý thuyết tiếng Việt và 2 ví dụ tình huống","3 câu hỏi tự biên soạn có giải thích lựa chọn"],"concept_ids":["S02-01","S02-02","S02-03","S02-04"],"formula_ids":["F02-01"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":21},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":154},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":8}},"missing_items":[]},{"los_id":"CFA26-10-01-LOS03","learning_goal_vi":"Mô tả professions và cách các nghề nghiệp tạo lập lòng tin.","status":"targeted_CFAI_Kaplan_SAPP_and_scenario_QA_pass","competency_criteria":["Phù hợp động từ và LOS CFAI 2026","Đối chiếu với Kaplan/SAPP cùng chủ đề","Có 4+ phần lý thuyết tiếng Việt và 2 ví dụ tình huống","3 câu hỏi tự biên soạn có giải thích lựa chọn"],"concept_ids":["S03-01","S03-02","S03-03","S03-04"],"formula_ids":["F03-01"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":22},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":154},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":6}},"missing_items":[]},{"los_id":"CFA26-10-01-LOS04","learning_goal_vi":"Mô tả lý do investment management cần chuẩn đạo đức cao.","status":"targeted_CFAI_Kaplan_SAPP_and_scenario_QA_pass","competency_criteria":["Phù hợp động từ và LOS CFAI 2026","Đối chiếu với Kaplan/SAPP cùng chủ đề","Có 4+ phần lý thuyết tiếng Việt và 2 ví dụ tình huống","3 câu hỏi tự biên soạn có giải thích lựa chọn"],"concept_ids":["S04-01","S04-02","S04-03","S04-04"],"formula_ids":["F04-01"],"example_ids":["E04-01","E04-02"],"question_ids":["Q04-01","Q04-02","Q04-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":23},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":155},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":9}},"missing_items":[]},{"los_id":"CFA26-10-01-LOS05","learning_goal_vi":"Giải thích professionalism trong investment management.","status":"targeted_CFAI_Kaplan_SAPP_and_scenario_QA_pass","competency_criteria":["Phù hợp động từ và LOS CFAI 2026","Đối chiếu với Kaplan/SAPP cùng chủ đề","Có 4+ phần lý thuyết tiếng Việt và 2 ví dụ tình huống","3 câu hỏi tự biên soạn có giải thích lựa chọn"],"concept_ids":["S05-01","S05-02","S05-03","S05-04"],"formula_ids":["F05-01"],"example_ids":["E05-01","E05-02"],"question_ids":["Q05-01","Q05-02","Q05-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":24},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":156},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":10}},"missing_items":[]},{"los_id":"CFA26-10-01-LOS06","learning_goal_vi":"Nhận diện các thách thức đối với ethical behavior.","status":"targeted_CFAI_Kaplan_SAPP_and_scenario_QA_pass","competency_criteria":["Phù hợp động từ và LOS CFAI 2026","Đối chiếu với Kaplan/SAPP cùng chủ đề","Có 4+ phần lý thuyết tiếng Việt và 2 ví dụ tình huống","3 câu hỏi tự biên soạn có giải thích lựa chọn"],"concept_ids":["S06-01","S06-02","S06-03","S06-04"],"formula_ids":["F06-01"],"example_ids":["E06-01","E06-02"],"question_ids":["Q06-01","Q06-02","Q06-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":27},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":156},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":11}},"missing_items":[]},{"los_id":"CFA26-10-01-LOS07","learning_goal_vi":"So sánh và đối chiếu ethical standards với legal standards.","status":"targeted_CFAI_Kaplan_SAPP_and_scenario_QA_pass","competency_criteria":["Phù hợp động từ và LOS CFAI 2026","Đối chiếu với Kaplan/SAPP cùng chủ đề","Có 4+ phần lý thuyết tiếng Việt và 2 ví dụ tình huống","3 câu hỏi tự biên soạn có giải thích lựa chọn"],"concept_ids":["S07-01","S07-02","S07-03","S07-04"],"formula_ids":["F07-01"],"example_ids":["E07-01","E07-02"],"question_ids":["Q07-01","Q07-02","Q07-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":30},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":156},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":12}},"missing_items":[]},{"los_id":"CFA26-10-01-LOS08","learning_goal_vi":"Mô tả một framework cho ethical decision making.","status":"targeted_CFAI_Kaplan_SAPP_and_scenario_QA_pass","competency_criteria":["Phù hợp động từ và LOS CFAI 2026","Đối chiếu với Kaplan/SAPP cùng chủ đề","Có 4+ phần lý thuyết tiếng Việt và 2 ví dụ tình huống","3 câu hỏi tự biên soạn có giải thích lựa chọn"],"concept_ids":["S08-01","S08-02","S08-03","S08-04"],"formula_ids":["F08-01"],"example_ids":["E08-01","E08-02"],"question_ids":["Q08-01","Q08-02","Q08-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":32},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":157},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":13}},"missing_items":[]}],"sections":[{"id":"S01-01","los_ids":["CFA26-10-01-LOS01"],"heading_vi":"Ethics, morality và hành vi","body_vi":"Ethics là hệ thống nguyên tắc đạo đức và các quy tắc hướng dẫn việc lựa chọn hành vi; không phải chỉ là compliance theo luật. Moral principles đưa ra chuẩn đúng/sai; standards of conduct cụ thể hóa kỳ vọng hành vi trong cộng đồng hoặc nghề nghiệp. Một lựa chọn có thể hợp pháp nhưng gây tổn hại lợi ích chính đáng của khách hàng."},{"id":"S01-02","los_ids":["CFA26-10-01-LOS01"],"heading_vi":"Stakeholders và xung đột","body_vi":"Stakeholders là các nhóm bị tác động trực tiếp hoặc gián tiếp bởi quyết định: khách hàng, đối tác, người lao động, công ty, nghề nghiệp và thị trường. Khi khuyến nghị một cổ phiếu, analyst cần nhận diện cả khách hàng hưởng lợi và những người chịu rủi ro vì thông tin gây hiểu lầm; lợi ích ngắn hạn cho người bán không đồng nghĩa hành vi đạo đức."},{"id":"S01-03","los_ids":["CFA26-10-01-LOS01"],"heading_vi":"Các mức chuẩn tắc","body_vi":"Nguyên tắc đạo đức là định hướng giá trị, còn rule là quy định áp dụng trong trường hợp cụ thể. Lý do một hành vi được chấp nhận không chỉ là tránh bị phạt mà còn bởi tính trung thực, công bằng và trách nhiệm trong điều kiện thông tin bất cân xứng."},{"id":"S01-04","los_ids":["CFA26-10-01-LOS01"],"heading_vi":"Ethical reasoning thực hành","body_vi":"Khi gặp xung đột, cần viết ra fact có thể xác minh, phân biệt assumptions, xác định người có thể bị hại và tìm lựa chọn không đặt lợi ích cá nhân lên trước. Phân tích cả hậu quả có thể xảy ra lẫn nghĩa vụ đối với khách hàng. Một quyết định không nên chỉ dựa vào việc “chưa có luật cấm”."},{"id":"S02-01","los_ids":["CFA26-10-01-LOS02"],"heading_vi":"Code of ethics làm gì","body_vi":"Code of ethics là tuyên bố định hướng những giá trị và nguyên tắc mà các thành viên nghề nghiệp phải theo đuổi, qua đó thiết lập kỳ vọng vượt trên lợi ích kinh tế ngắn hạn. Code thường mang tính nguyên tắc, standards cung cấp điều khoản hành động cụ thể."},{"id":"S02-02","los_ids":["CFA26-10-01-LOS02"],"heading_vi":"Xác lập bản sắc nghề nghiệp","body_vi":"Một profession tồn tại vì xã hội tin rằng người hành nghề vừa có năng lực chuyên môn vừa dùng năng lực đó có trách nhiệm. Code giúp tạo ngôn ngữ chung, cam kết phục vụ khách hàng và cơ chế đánh giá hành vi cho tất cả thành viên."},{"id":"S02-03","los_ids":["CFA26-10-01-LOS02"],"heading_vi":"Quan hệ code, standards và enforcement","body_vi":"Code đơn thuần không đủ nếu thiếu guidance, giáo dục, giám sát và cơ chế kỷ luật. Standards cụ thể hóa tình huống như conflicts of interest, material nonpublic information, confidentiality. Thực hành cần kết hợp culture và review thay vì chỉ yêu cầu ký cam kết."},{"id":"S02-04","los_ids":["CFA26-10-01-LOS02"],"heading_vi":"Vai trò với người dùng dịch vụ","body_vi":"Khách hàng thường không thể trực tiếp đánh giá chất lượng research, valuation hay rủi ro được che giấu. Một code minh bạch được thực thi đáng tin giúp giảm tình trạng bất cân xứng thông tin; nếu enforcement yếu, niềm tin vẫn có thể suy giảm."},{"id":"S03-01","los_ids":["CFA26-10-01-LOS03"],"heading_vi":"Đặc trưng một profession","body_vi":"Professions thường có hệ thống kiến thức chuyên sâu, đào tạo/kiểm tra năng lực, standards đạo đức, trách nhiệm với khách hàng và sự giám sát của cơ quan nghề nghiệp hoặc cộng đồng. Tính chuyên nghiệp không đồng nhất với chức danh hay mức thu nhập."},{"id":"S03-02","los_ids":["CFA26-10-01-LOS03"],"heading_vi":"Asymmetric information","body_vi":"Nhà đầu tư không dễ biết advisor đã kiểm chứng dữ liệu hay dùng đúng discount rate, nên có information asymmetry. Nghề nghiệp xây dựng trust bằng qualification, integrity, disclosure, records và sanctions khi không đạt expectations."},{"id":"S03-03","los_ids":["CFA26-10-01-LOS03"],"heading_vi":"Service to others","body_vi":"Một profession đề cao phục vụ lợi ích khách hàng, cộng đồng và tính toàn vẹn thị trường, đôi khi phải từ chối lợi ích tài chính trước mắt. Fiduciary-type obligations có thể khắt khe hơn giao dịch commercial thông thường."},{"id":"S03-04","los_ids":["CFA26-10-01-LOS03"],"heading_vi":"Tái tạo niềm tin lâu dài","body_vi":"Trust là kết quả của chất lượng kỹ thuật, hành vi nhất quán và enforcement công bằng. Một vài scandals có thể làm suy giảm niềm tin toàn ngành, khiến costs of capital và costs of due diligence tăng lên."},{"id":"S04-01","los_ids":["CFA26-10-01-LOS04"],"heading_vi":"Quyền hạn trên tài sản người khác","body_vi":"Manager/analyst ảnh hưởng đến hưu trí, tiết kiệm và mục tiêu tài chính của khách hàng. Khách hàng chấp nhận ủy quyền trong điều kiện không thể giám sát mọi quyết định; vì thế cần tiêu chuẩn trung thực, năng lực và thận trọng cao."},{"id":"S04-02","los_ids":["CFA26-10-01-LOS04"],"heading_vi":"Rủi ro hệ thống và ngoại tác","body_vi":"Thông tin sai hoặc thao túng giá có thể làm méo allocation of capital, giảm liquidity và độ tin cậy của benchmarks. Tác động đạo đức không chỉ là P&L của một nhà đầu tư, mà còn ảnh hưởng cơ chế vận hành thị trường."},{"id":"S04-03","los_ids":["CFA26-10-01-LOS04"],"heading_vi":"Xung đột kinh tế","body_vi":"Research analysts, brokers, wealth managers và sales teams có động cơ phí/bonus tạo khác biệt với mục tiêu khách hàng. Cơ chế tránh/tiết lộ xung đột và kiểm soát disclosure làm giảm rủi ro tự lợi."},{"id":"S04-04","los_ids":["CFA26-10-01-LOS04"],"heading_vi":"Trust nâng hiệu quả thị trường","body_vi":"Nếu nhà đầu tư phải nghi ngờ mọi báo cáo, chi phí xác minh tăng, họ có thể đòi risk premium lớn hơn hoặc rời thị trường. Ethical conduct củng cố market participation và confidence nhưng không bảo đảm loại bỏ biến động tài sản."},{"id":"S05-01","los_ids":["CFA26-10-01-LOS05"],"heading_vi":"Professionalism khác job title","body_vi":"Professionalism thể hiện competence, diligence, independence, integrity và accountability trong mọi công việc chuyên môn. Danh thiếp ghi “senior analyst” không thay thế năng lực phân tích và hành vi có trách nhiệm."},{"id":"S05-02","los_ids":["CFA26-10-01-LOS05"],"heading_vi":"Fiduciary versus suitability","body_vi":"Fiduciary standard đòi hỏi quản lý tài sản cho lợi ích khách hàng, thận trọng và loyal. Suitability standard nhấn mạnh sản phẩm/khuyến nghị phù hợp mục tiêu/ràng buộc của khách hàng. Hai chuẩn này có phạm vi nghĩa vụ khác nhau; không được giả định phù hợp là đã tối ưu lợi ích."},{"id":"S05-03","los_ids":["CFA26-10-01-LOS05"],"heading_vi":"Professional judgment","body_vi":"Independent judgment đòi hỏi sử dụng bằng chứng khách quan, tránh áp lực deal fees và không biến ý kiến thành fact. Khi thông tin chưa đầy đủ, phải công bố assumptions, uncertainties và giới hạn của quy trình."},{"id":"S05-04","los_ids":["CFA26-10-01-LOS05"],"heading_vi":"Lifelong competence","body_vi":"Năng lực phải được duy trì khi công việc và công cụ mới thay đổi. Việc học thêm, đánh giá thực hành và xin tư vấn chuyên gia trong lĩnh vực mới là hành vi chuyên nghiệp; tự tin quá mức khi không đủ kiến thức tạo rủi ro cho khách hàng."},{"id":"S06-01","los_ids":["CFA26-10-01-LOS06"],"heading_vi":"Overconfidence về đạo đức cá nhân","body_vi":"Người hành nghề có thể tin mình luôn trung thực và bỏ qua nguy cơ bị ảnh hưởng bởi incentives, peers hoặc authority. Self-perception tốt không phải bằng chứng rằng quyết định trong pressure sẽ khách quan."},{"id":"S06-02","los_ids":["CFA26-10-01-LOS06"],"heading_vi":"Situational influences","body_vi":"Áp lực chỉ tiêu, loyalty với nhóm, người quản lý có quyền thưởng/phạt và normalization of deviance khiến người giỏi cũng hành động sai. Nhận diện structural pressures trước khi có dilemma là cách phòng ngừa hiệu quả."},{"id":"S06-03","los_ids":["CFA26-10-01-LOS06"],"heading_vi":"Compliance-only mindset","body_vi":"Thực hiện đúng minimum rules nhưng bỏ qua spirit of ethics có thể dẫn đến marketing misleading hoặc cấu trúc giao dịch trốn tránh trách nhiệm. Checklist pháp lý hữu ích nhưng không thay được ethical reasoning về consequences."},{"id":"S06-04","los_ids":["CFA26-10-01-LOS06"],"heading_vi":"Khắc phục","body_vi":"Thiết kế incentive tránh thiên lệch, tạo speak-up mechanisms, independent review, escalation channels, challenge assumptions và phản biện lựa chọn. Cần chuẩn bị phương án từ chối khi yêu cầu trái standards thay vì chỉ dựa thiện chí cá nhân."},{"id":"S07-01","los_ids":["CFA26-10-01-LOS07"],"heading_vi":"Ethical không đồng nhất legal","body_vi":"Law xác lập yêu cầu pháp lý có enforcement của cơ quan chức năng; ethics là tập hợp nguyên tắc hành vi có thể đặt chuẩn cao hơn luật. Một hành vi được luật cho phép chưa chắc công bằng, trung thực hoặc đáp ứng nghĩa vụ đối với khách hàng."},{"id":"S07-02","los_ids":["CFA26-10-01-LOS07"],"heading_vi":"Bốn góc phần tư hành vi","body_vi":"Có thể legal+ethical, legal+unethical, illegal+unethical và thậm chí illegal nhưng có mục đích đạo đức trong một số bối cảnh. Trong chuẩn CFA, khi conflict giữa applicable laws/rules và Code/Standards, thành viên phải tuân thủ quy định nghiêm ngặt hơn; không được tự biện hộ vi phạm luật vì mục đích đạo đức."},{"id":"S07-03","los_ids":["CFA26-10-01-LOS07"],"heading_vi":"Khác biệt phạm vi áp dụng","body_vi":"Laws thay đổi theo jurisdiction và đôi khi chậm hơn innovation; professional standards có thể đặt common obligations xuyên biên giới. Ethical standards không bỏ qua local legal duties, và tuân thủ luật không tự động là đủ nếu Code nghiêm hơn."},{"id":"S07-04","los_ids":["CFA26-10-01-LOS07"],"heading_vi":"Ethical compliance khi xuyên biên giới","body_vi":"Xác định địa điểm làm việc/giao dịch, applicable rules, những điều kiện nghiêm ngặt hơn và yêu cầu tách khỏi vi phạm. Trong nghi ngờ, tham vấn compliance/legal counsel thay vì chọn chuẩn thấp nhất."},{"id":"S08-01","los_ids":["CFA26-10-01-LOS08"],"heading_vi":"Xác định facts và dilemma","body_vi":"Bắt đầu từ sự kiện có căn cứ, rủi ro, phạm vi quyết định và các bên liên quan. Phân biệt fact, opinion và chưa biết; tránh framing sai khiến giải pháp nghiêng về mục tiêu doanh số ngay từ đầu."},{"id":"S08-02","los_ids":["CFA26-10-01-LOS08"],"heading_vi":"Nhận diện duties, stakeholders và situational influence","body_vi":"Liệt kê clients/employer/colleagues/market, duties tương ứng, conflicts, incentives và điểm mù của bản thân. Một quyết định có thể có nhiều bên bị tác động, không nên chỉ hỏi người trả tiền có hài lòng hay không."},{"id":"S08-03","los_ids":["CFA26-10-01-LOS08"],"heading_vi":"Xây dựng và đánh giá alternatives","body_vi":"Đối chiếu phương án với laws, Code/Standards và consequences ngắn-dài hạn; tính đến reputational, market trust và fairness. Tham vấn peers/compliance khi phù hợp, cân nhắc cách diễn giải với stakeholder độc lập."},{"id":"S08-04","los_ids":["CFA26-10-01-LOS08"],"heading_vi":"Quyết định, hành động, phản tư","body_vi":"Chọn phương án có lý do vững, ghi nhận rationale, communicate, monitor outcomes và review. Framework mang tính iterative: thông tin mới có thể khiến quay lại xác minh facts hoặc điều chỉnh lựa chọn, không phải quy trình một chiều đóng cứng."}],"formulae":[{"id":"F01-01","los_ids":["CFA26-10-01-LOS01"],"expression":"Ethical review checklist: Facts → Stakeholders → Duties and Standards → Alternatives → Decision → Review","variables":["Mô hình ra quyết định mô tả, không phải công thức toán học trong CFA Institute Curriculum."],"assumptions":["Quy trình lặp lại khi có thông tin mới; không thay thế việc áp dụng Standards cụ thể."]},{"id":"F02-01","los_ids":["CFA26-10-01-LOS02"],"expression":"Ethical review checklist: Facts → Stakeholders → Duties and Standards → Alternatives → Decision → Review","variables":["Mô hình ra quyết định mô tả, không phải công thức toán học trong CFA Institute Curriculum."],"assumptions":["Quy trình lặp lại khi có thông tin mới; không thay thế việc áp dụng Standards cụ thể."]},{"id":"F03-01","los_ids":["CFA26-10-01-LOS03"],"expression":"Ethical review checklist: Facts → Stakeholders → Duties and Standards → Alternatives → Decision → Review","variables":["Mô hình ra quyết định mô tả, không phải công thức toán học trong CFA Institute Curriculum."],"assumptions":["Quy trình lặp lại khi có thông tin mới; không thay thế việc áp dụng Standards cụ thể."]},{"id":"F04-01","los_ids":["CFA26-10-01-LOS04"],"expression":"Ethical review checklist: Facts → Stakeholders → Duties and Standards → Alternatives → Decision → Review","variables":["Mô hình ra quyết định mô tả, không phải công thức toán học trong CFA Institute Curriculum."],"assumptions":["Quy trình lặp lại khi có thông tin mới; không thay thế việc áp dụng Standards cụ thể."]},{"id":"F05-01","los_ids":["CFA26-10-01-LOS05"],"expression":"Ethical review checklist: Facts → Stakeholders → Duties and Standards → Alternatives → Decision → Review","variables":["Mô hình ra quyết định mô tả, không phải công thức toán học trong CFA Institute Curriculum."],"assumptions":["Quy trình lặp lại khi có thông tin mới; không thay thế việc áp dụng Standards cụ thể."]},{"id":"F06-01","los_ids":["CFA26-10-01-LOS06"],"expression":"Ethical review checklist: Facts → Stakeholders → Duties and Standards → Alternatives → Decision → Review","variables":["Mô hình ra quyết định mô tả, không phải công thức toán học trong CFA Institute Curriculum."],"assumptions":["Quy trình lặp lại khi có thông tin mới; không thay thế việc áp dụng Standards cụ thể."]},{"id":"F07-01","los_ids":["CFA26-10-01-LOS07"],"expression":"Ethical review checklist: Facts → Stakeholders → Duties and Standards → Alternatives → Decision → Review","variables":["Mô hình ra quyết định mô tả, không phải công thức toán học trong CFA Institute Curriculum."],"assumptions":["Quy trình lặp lại khi có thông tin mới; không thay thế việc áp dụng Standards cụ thể."]},{"id":"F08-01","los_ids":["CFA26-10-01-LOS08"],"expression":"Ethical review checklist: Facts → Stakeholders → Duties and Standards → Alternatives → Decision → Review","variables":["Mô hình ra quyết định mô tả, không phải công thức toán học trong CFA Institute Curriculum."],"assumptions":["Quy trình lặp lại khi có thông tin mới; không thay thế việc áp dụng Standards cụ thể."]}],"worked_examples":[{"id":"E01-01","los_ids":["CFA26-10-01-LOS01"],"problem":"Analyst được ngân hàng đầu tư đề nghị nâng price target để hỗ trợ một thương vụ.","solution_steps":["Nhận diện stakeholders: nhà đầu tư dựa vào báo cáo, issuer, analyst, employer và thị trường.","Việc “giúp công ty kiếm thêm phí” không làm cho báo cáo sai lệch trở thành hợp đạo đức."],"answer":"Giữ giả định độc lập và từ chối điều chỉnh kết luận không có bằng chứng."},{"id":"E01-02","los_ids":["CFA26-10-01-LOS01"],"problem":"Một sản phẩm được bán đúng luật nhưng thông báo các rủi ro trọng yếu bằng chữ rất nhỏ.","solution_steps":["Legal compliance không chứng minh khách hàng được đối xử trung thực và công bằng.","Cần diễn đạt dễ hiểu, đầy đủ rủi ro và chi phí thực, tránh đánh đổi lòng tin lấy doanh số."],"answer":"Đánh giá việc che giấu rủi ro là vấn đề đạo đức dù thủ tục pháp lý tối thiểu đã được làm."},{"id":"E02-01","los_ids":["CFA26-10-01-LOS02"],"problem":"Một tổ chức có khẩu hiệu “khách hàng là trên hết” nhưng trả bonus theo số sản phẩm bán.","solution_steps":["Khẩu hiệu chỉ là aspirational code; incentive tạo xung đột khi advisor có thể bán sản phẩm không phù hợp.","Cần standards, kiểm soát suitability, đánh giá chất lượng tư vấn và trách nhiệm kỷ luật."],"answer":"Code có giá trị khi được thực thi qua quy trình quyết định và giám sát."},{"id":"E02-02","los_ids":["CFA26-10-01-LOS02"],"problem":"Investment association xây dựng code nhưng không có quy định xử lý người công bố lợi nhuận sai.","solution_steps":["Code đưa định hướng nhưng cơ chế răn đe yếu.","Cần đưa thêm standards, monitoring, sanctions và education để tăng trust."],"answer":"Code xác lập kỳ vọng nghề nghiệp; việc thực thi chuyển các nguyên tắc thành hành vi."},{"id":"E03-01","los_ids":["CFA26-10-01-LOS03"],"problem":"Khách hàng không thể kiểm tra thuật toán định giá danh mục của manager.","solution_steps":["Kiểm định năng lực, chính sách minh bạch và công bố limitation làm giảm information asymmetry.","Việc audit khách quan và nghĩa vụ đạo đức tạo lý do để khách hàng tin nhà quản lý."],"answer":"Trust đến từ hệ thống kỹ thuật và hành vi có thể kiểm chứng chứ không chỉ marketing."},{"id":"E03-02","los_ids":["CFA26-10-01-LOS03"],"problem":"Một advisor đạt chứng chỉ nhưng che giấu phí sản phẩm.","solution_steps":["Chứng chỉ chứng minh một mức kiến thức, không bảo đảm tính trung thực trong từng giao dịch.","Thiếu minh bạch phí làm suy giảm chính điều kiện trust mà profession muốn tạo."],"answer":"Competence và ethics là hai điều kiện bổ trợ, không thể thay thế nhau."},{"id":"E04-01","los_ids":["CFA26-10-01-LOS04"],"problem":"Manager nhận hoa hồng cao hơn nếu chuyển quỹ khách hàng sang sản phẩm có phí lớn.","solution_steps":["Manager có conflict với lợi ích dài hạn khách hàng.","So sánh cost, suitability, expected benefit và disclose/conflict management trước recommendation."],"answer":"Không được lấy incentives để biện minh sản phẩm bất lợi khách hàng."},{"id":"E04-02","los_ids":["CFA26-10-01-LOS04"],"problem":"Báo cáo định giá cố tình bỏ debt covenant breach để issuer vay rẻ hơn.","solution_steps":["Người mua bond chịu credit risk bị che giấu; vốn bị phân bổ sai.","Tác hại vượt ra ngoài một giao dịch, làm giảm lòng tin vào báo cáo."],"answer":"Chuẩn đạo đức cao bảo vệ clients và tính toàn vẹn capital markets."},{"id":"E05-01","los_ids":["CFA26-10-01-LOS05"],"problem":"Advisor được yêu cầu khuyến nghị sản phẩm crypto dù chưa hiểu custody risks.","solution_steps":["Professionalism đòi hỏi bổ sung competence trước khi thực hiện trách nhiệm.","Cần nghiên cứu hoặc chuyển người có năng lực; không nên giả lập chắc chắn về rủi ro."],"answer":"Chức danh CFA candidate không chứng minh mọi kỹ năng chuyên ngành."},{"id":"E05-02","los_ids":["CFA26-10-01-LOS05"],"problem":"Manager có hai sản phẩm đều phù hợp risk tolerance, nhưng một có phí cao hơn do incentive.","solution_steps":["Suitability chưa đủ kết luận manager đã đặt lợi ích client trước.","Cần đánh giá lợi ích ròng, conflicts và nghĩa vụ loyalty, prudence, care."],"answer":"Khác biệt giữa phù hợp và best interest có thể quyết định kết luận ethical."},{"id":"E06-01","los_ids":["CFA26-10-01-LOS06"],"problem":"Supervisor yêu cầu ưu tiên khách hàng VIP dù trade allocation policy quy định cùng điều kiện.","solution_steps":["Authority pressure có thể khiến junior advisor rationalize hành vi không công bằng.","Review allocation rules, ghi nhận vấn đề và escalate nếu cần."],"answer":"Situational influence, không phải tính cách cá nhân đơn lẻ, là rủi ro đạo đức."},{"id":"E06-02","los_ids":["CFA26-10-01-LOS06"],"problem":"Team được thưởng cao nếu tất cả dự báo EPS lạc quan vượt consensus.","solution_steps":["Group pressure và incentive cấu trúc có thể khiến dự báo thiên lệch.","Yêu cầu forecast độc lập, lưu giả định, peer review từ nhóm không có incentives như vậy."],"answer":"Phòng ngừa bằng policies và counter-incentives rõ ràng."},{"id":"E07-01","los_ids":["CFA26-10-01-LOS07"],"problem":"Một nước chưa cấm giao dịch theo tin nội bộ, trong khi Code CFA cấm.","solution_steps":["Dù local law không cấm, member/candidate vẫn chịu Standard II(A) nếu thực hiện trading trên material nonpublic information.","Tuân thủ chuẩn nghiêm hơn giữa các quy định liên quan."],"answer":"Hành vi có thể legal theo luật sở tại nhưng vẫn vi phạm Code/Standards."},{"id":"E07-02","los_ids":["CFA26-10-01-LOS07"],"problem":"Regulation cấm một sản phẩm, marketing team cho rằng disclosure đầy đủ nên có thể bán.","solution_steps":["Disclosure không biến hành vi trái law thành acceptable.","Phải tuân applicable regulation và không tham gia bán; seek legal advice nếu quy tắc mâu thuẫn."],"answer":"“Mục đích tốt” không thay nghĩa vụ tuân thủ pháp luật."},{"id":"E08-01","los_ids":["CFA26-10-01-LOS08"],"problem":"Analyst nghi ngờ báo cáo ngân hàng bị sửa để phù hợp deal.","solution_steps":["Ghi facts: source data, changes, người yêu cầu; nhận diện stakeholders và nghĩa vụ independence, accuracy.","Cân nhắc independent review, escalation, không công bố số chưa kiểm chứng; document actions."],"answer":"Framework giúp xử lý dilemma bằng dữ kiện, duties, options và review."},{"id":"E08-02","los_ids":["CFA26-10-01-LOS08"],"problem":"Asset manager phát hiện một data vendor cung cấp giá giá chưa kiểm chứng.","solution_steps":["Xác định khách hàng nào bị ảnh hưởng đến valuation NAV, kiểm tra dữ liệu thay thế.","Tạm tránh dùng prices chưa xác nhận, thông báo theo obligations, review control."],"answer":"Ethical judgment phải cập nhật khi thêm thông tin; framework là iterative."}],"questions":[{"id":"Q01-01","los_ids":["CFA26-10-01-LOS01"],"stem":"Ethics trong đầu tư là?","options":["Chỉ các quy định pháp luật có chế tài","Hệ thống nguyên tắc dẫn dắt hành vi đúng/sai","Chỉ là tối đa hóa lợi nhuận công ty"],"correct_option":1,"explanation":"Ethics rộng hơn luật pháp và đòi hỏi đánh giá lợi ích của các stakeholders; có những hành vi hợp pháp vẫn phi đạo đức."},{"id":"Q01-02","los_ids":["CFA26-10-01-LOS01"],"stem":"Ai là stakeholder của báo cáo phân tích cổ phiếu?","options":["Chỉ công ty phát hành","Chỉ người viết báo cáo","Khách hàng, employer, đồng nghiệp và thành viên thị trường bị ảnh hưởng"],"correct_option":2,"explanation":"Stakeholder bao gồm mọi nhóm chịu tác động trực tiếp hoặc gián tiếp; không chỉ người trả phí hay người sở hữu chứng khoán."},{"id":"Q01-03","los_ids":["CFA26-10-01-LOS01"],"stem":"Một analyst biết marketing chưa vi phạm luật nhưng thông tin trình bày đánh lừa khách hàng. Tốt nhất?","options":["Xem xét tính trung thực và lợi ích khách hàng trước khi phát hành","Đăng vì luật cho phép","Xóa bằng chứng và tiếp tục"],"correct_option":0,"explanation":"Tiêu chuẩn đạo đức có thể đòi hỏi hành vi cao hơn mức tối thiểu của pháp luật; phải giải quyết vấn đề disclosure và misrepresentation."},{"id":"Q02-01","los_ids":["CFA26-10-01-LOS02"],"stem":"Khác biệt code và standards?","options":["Standards không liên quan code","Code nêu nguyên tắc, standards cụ thể hóa nghĩa vụ","Code chỉ về tiền lương"],"correct_option":1,"explanation":"Code thể hiện giá trị và cam kết nền tảng; Standards là những quy tắc ứng xử áp dụng vào hoạt động nghề nghiệp."},{"id":"Q02-02","los_ids":["CFA26-10-01-LOS02"],"stem":"Mục tiêu của profession code là?","options":["Bảo đảm mọi thương vụ có lợi nhuận","Cấm mọi cạnh tranh","Tạo chuẩn chung nâng lòng tin và trách nhiệm"],"correct_option":2,"explanation":"Code định nghĩa các giá trị nghề nghiệp, giúp khách hàng biết người hành nghề phải ưu tiên trách nhiệm gì dù khách hàng khó tự kiểm chứng chất lượng dịch vụ."},{"id":"Q02-03","los_ids":["CFA26-10-01-LOS02"],"stem":"Một code viết tốt nhưng không được thực thi thì?","options":["Cần guidance, enforcement và culture hỗ trợ","Không có vấn đề vì đạo đức chỉ là khẩu hiệu","Luôn đủ để bảo vệ khách"],"correct_option":0,"explanation":"Niềm tin chỉ bền vững khi lời cam kết trong code gắn với standards và hậu quả thực tế đối với hành vi vi phạm."},{"id":"Q03-01","los_ids":["CFA26-10-01-LOS03"],"stem":"Yếu tố nào đặc trưng profession?","options":["Không cần chuẩn năng lực","Chuyên môn và nghĩa vụ đạo đức đối với người sử dụng dịch vụ","Lợi nhuận cá nhân bằng mọi giá"],"correct_option":1,"explanation":"Profession thiết lập chuẩn chuyên môn và ứng xử, có cơ chế giữ trust vì người dùng thường khó đánh giá chất lượng dịch vụ."},{"id":"Q03-02","los_ids":["CFA26-10-01-LOS03"],"stem":"Information asymmetry khiến?","options":["Mọi lời khuyên đều đúng","Không cần disclosure","Khách hàng khó tự đánh giá chất lượng advice"],"correct_option":2,"explanation":"Do khách hàng khó quan sát quá trình và chất lượng thực, thông tin bất cân xứng tạo nhu cầu về code, qualifications và accountability."},{"id":"Q03-03","los_ids":["CFA26-10-01-LOS03"],"stem":"Một scand​al disclosure làm thị trường mất niềm tin. Kết luận?","options":["Hành vi cá nhân có thể hại toàn profession","Chỉ một người bị ảnh hưởng","Không liên quan nghề nghiệp"],"correct_option":0,"explanation":"Hành vi gian dối gây externality lên niềm tin của khách hàng và uy tín ngành; ethical governance là lợi ích chung."},{"id":"Q04-01","los_ids":["CFA26-10-01-LOS04"],"stem":"Vì sao ngành đầu tư cần ethical standards cao?","options":["Để thay thế hoàn toàn pháp luật","Ảnh hưởng tới tài sản ủy thác và niềm tin thị trường","Vì mọi giao dịch chắc chắn thắng"],"correct_option":1,"explanation":"Đầu tư có information asymmetry, client agency relationships và market-wide externalities; standards bổ sung chứ không thay luật."},{"id":"Q04-02","los_ids":["CFA26-10-01-LOS04"],"stem":"Bán quỹ phí cao vì nhận bonus là ví dụ?","options":["Portfolio duration","Yield curve","Conflict of interest"],"correct_option":2,"explanation":"Incentive của advisor có thể khác lợi ích khách hàng; nhận diện/giải quyết conflict quan trọng hơn commission."},{"id":"Q04-03","los_ids":["CFA26-10-01-LOS04"],"stem":"Việc công bố sai rủi ro trái phiếu có thể?","options":["Làm méo pricing và suy giảm trust toàn thị trường","Không ảnh hưởng ngoài issuer","Tự động tăng trust"],"correct_option":0,"explanation":"Thông tin sai ảnh hưởng capital allocation và người giao dịch thứ cấp; hậu quả rộng hơn issuer."},{"id":"Q05-01","los_ids":["CFA26-10-01-LOS05"],"stem":"Professionalism thể hiện rõ nhất qua?","options":["Tự nhận có năng lực cao","Competence và independent ethical judgment","Không cần cập nhật chuyên môn"],"correct_option":1,"explanation":"Tính chuyên nghiệp được đánh giá qua hành vi cẩn trọng, độc lập, competence và trách nhiệm chứ không chỉ danh hiệu."},{"id":"Q05-02","los_ids":["CFA26-10-01-LOS05"],"stem":"Suitability thường nhấn mạnh điều gì?","options":["Mọi sản phẩm phù hợp đều không có conflict","Client luôn chịu loss bằng 0","Khuyến nghị phù hợp mục tiêu, rủi ro, ràng buộc"],"correct_option":2,"explanation":"Suitability đánh giá tương thích với tình hình của client; không tự động loại bỏ xung đột lợi ích."},{"id":"Q05-03","los_ids":["CFA26-10-01-LOS05"],"stem":"Analyst thiếu kiến thức nhưng vẫn khẳng định mô hình mới chắc chắn đúng?","options":["Thiếu competence và prudence","Professionalism cao","Chỉ lỗi market beta"],"correct_option":0,"explanation":"Cần biết giới hạn năng lực, xác minh assumptions và tìm hỗ trợ trước khi đưa ra kết luận có thể ảnh hưởng client."},{"id":"Q06-01","los_ids":["CFA26-10-01-LOS06"],"stem":"Một thách thức đạo đức quan trọng?","options":["Lợi suất phi rủi ro","Áp lực nhóm và incentives","Tính toán standard deviation"],"correct_option":1,"explanation":"Situational influences và self-serving bias có thể khiến người vốn tin mình đạo đức vẫn đưa ra lựa chọn sai."},{"id":"Q06-02","los_ids":["CFA26-10-01-LOS06"],"stem":"“Nếu luật không cấm thì chắc chắn đúng” là?","options":["Cách tính IRR","Lý tưởng professionalism","Compliance-only mindset"],"correct_option":2,"explanation":"Chuẩn đạo đức có thể vượt luật; xem xét consequences và stakeholders thay vì legal minimum."},{"id":"Q06-03","los_ids":["CFA26-10-01-LOS06"],"stem":"Thao tác nào giúp giảm ethical blind spots?","options":["Independent review và escalation path","Ẩn điều khoản phí","Không lưu quyết định"],"correct_option":0,"explanation":"Independent review giúp phát hiện groupthink, incentives và thông tin thiếu trong quyết định."},{"id":"Q07-01","los_ids":["CFA26-10-01-LOS07"],"stem":"Khi local law lỏng hơn CFA Standards?","options":["Chỉ tuân local law","Tuân chuẩn nghiêm ngặt hơn","Được chọn chuẩn cho lợi nhuận cao nhất"],"correct_option":1,"explanation":"CFA Standard I(A) yêu cầu dùng mức yêu cầu nghiêm ngặt hơn khi laws/rules/Code có xung đột liên quan."},{"id":"Q07-02","los_ids":["CFA26-10-01-LOS07"],"stem":"Nếu hành vi hợp pháp?","options":["Tự động ethical","Tự động phù hợp fiduciary duty","Vẫn phải đánh giá theo ethical standards"],"correct_option":2,"explanation":"Ethics có thể cao hơn legal minimum; cần xem công bằng, trung thực, conflicts và hậu quả."},{"id":"Q07-03","los_ids":["CFA26-10-01-LOS07"],"stem":"Đối với hành vi trái luật nhưng theo ý kiến cá nhân là có lợi, CFA member nên?","options":["Không tham gia, tìm giải pháp hợp pháp và tham vấn","Thực hiện vì mục tiêu tốt","Ẩn giao dịch"],"correct_option":0,"explanation":"Không thể lấy ý định tốt để biện hộ vi phạm applicable law; phải tuân các quy định có hiệu lực."},{"id":"Q08-01","los_ids":["CFA26-10-01-LOS08"],"stem":"Bước đầu thích hợp của ethical framework?","options":["Chỉ hỏi supervisor có thưởng không","Xác định facts và stakeholders","Chọn phương án lợi nhuận cao nhất"],"correct_option":1,"explanation":"Không đủ facts và stakeholders thì không thể đánh giá duties, options và consequences hợp lý."},{"id":"Q08-02","los_ids":["CFA26-10-01-LOS08"],"stem":"Framework tốt có tính chất?","options":["Không xét incentives","Không bao giờ điều chỉnh","Lặp lại khi xuất hiện thông tin mới"],"correct_option":2,"explanation":"Decision-making framework thường iterative; cần quay lại facts/options khi phát hiện dữ liệu hoặc ảnh hưởng mới."},{"id":"Q08-03","los_ids":["CFA26-10-01-LOS08"],"stem":"Chọn phương án tối ưu theo framework cần cân nhắc?","options":["Standards, duties và hậu quả với stakeholders","Chỉ outcome cá nhân","Chỉ pháp luật tối thiểu"],"correct_option":0,"explanation":"Ethics đòi hỏi đánh giá consequences, obligations và conflicts không thể giản lược chỉ tối đa hóa compensation."}],"flashcards":[{"id":"C01-01","los_ids":["CFA26-10-01-LOS01"],"front":"Ethics, morality và hành vi — nêu ý nghĩa và áp dụng?","back":"Ethics là hệ thống nguyên tắc đạo đức và các quy tắc hướng dẫn việc lựa chọn hành vi; không phải chỉ là compliance theo luật. Moral principles đưa ra chuẩn đúng/sai; standards of conduct cụ thể hóa kỳ vọng hành vi trong cộng đồng hoặc nghề nghiệp. Một lựa chọn có thể hợp pháp nhưng gây tổn hại lợi ích chính đáng của khách hàng."},{"id":"C01-02","los_ids":["CFA26-10-01-LOS01"],"front":"Stakeholders và xung đột — nêu ý nghĩa và áp dụng?","back":"Stakeholders là các nhóm bị tác động trực tiếp hoặc gián tiếp bởi quyết định: khách hàng, đối tác, người lao động, công ty, nghề nghiệp và thị trường. Khi khuyến nghị một cổ phiếu, analyst cần nhận diện cả khách hàng hưởng lợi và những người chịu rủi ro vì thông tin gây hiểu lầm; lợi ích ngắn hạn cho người bán không đồng nghĩa hành vi đạo đức."},{"id":"C01-03","los_ids":["CFA26-10-01-LOS01"],"front":"Các mức chuẩn tắc — nêu ý nghĩa và áp dụng?","back":"Nguyên tắc đạo đức là định hướng giá trị, còn rule là quy định áp dụng trong trường hợp cụ thể. Lý do một hành vi được chấp nhận không chỉ là tránh bị phạt mà còn bởi tính trung thực, công bằng và trách nhiệm trong điều kiện thông tin bất cân xứng."},{"id":"C02-01","los_ids":["CFA26-10-01-LOS02"],"front":"Code of ethics làm gì — nêu ý nghĩa và áp dụng?","back":"Code of ethics là tuyên bố định hướng những giá trị và nguyên tắc mà các thành viên nghề nghiệp phải theo đuổi, qua đó thiết lập kỳ vọng vượt trên lợi ích kinh tế ngắn hạn. Code thường mang tính nguyên tắc, standards cung cấp điều khoản hành động cụ thể."},{"id":"C02-02","los_ids":["CFA26-10-01-LOS02"],"front":"Xác lập bản sắc nghề nghiệp — nêu ý nghĩa và áp dụng?","back":"Một profession tồn tại vì xã hội tin rằng người hành nghề vừa có năng lực chuyên môn vừa dùng năng lực đó có trách nhiệm. Code giúp tạo ngôn ngữ chung, cam kết phục vụ khách hàng và cơ chế đánh giá hành vi cho tất cả thành viên."},{"id":"C02-03","los_ids":["CFA26-10-01-LOS02"],"front":"Quan hệ code, standards và enforcement — nêu ý nghĩa và áp dụng?","back":"Code đơn thuần không đủ nếu thiếu guidance, giáo dục, giám sát và cơ chế kỷ luật. Standards cụ thể hóa tình huống như conflicts of interest, material nonpublic information, confidentiality. Thực hành cần kết hợp culture và review thay vì chỉ yêu cầu ký cam kết."},{"id":"C03-01","los_ids":["CFA26-10-01-LOS03"],"front":"Đặc trưng một profession — nêu ý nghĩa và áp dụng?","back":"Professions thường có hệ thống kiến thức chuyên sâu, đào tạo/kiểm tra năng lực, standards đạo đức, trách nhiệm với khách hàng và sự giám sát của cơ quan nghề nghiệp hoặc cộng đồng. Tính chuyên nghiệp không đồng nhất với chức danh hay mức thu nhập."},{"id":"C03-02","los_ids":["CFA26-10-01-LOS03"],"front":"Asymmetric information — nêu ý nghĩa và áp dụng?","back":"Nhà đầu tư không dễ biết advisor đã kiểm chứng dữ liệu hay dùng đúng discount rate, nên có information asymmetry. Nghề nghiệp xây dựng trust bằng qualification, integrity, disclosure, records và sanctions khi không đạt expectations."},{"id":"C03-03","los_ids":["CFA26-10-01-LOS03"],"front":"Service to others — nêu ý nghĩa và áp dụng?","back":"Một profession đề cao phục vụ lợi ích khách hàng, cộng đồng và tính toàn vẹn thị trường, đôi khi phải từ chối lợi ích tài chính trước mắt. Fiduciary-type obligations có thể khắt khe hơn giao dịch commercial thông thường."},{"id":"C04-01","los_ids":["CFA26-10-01-LOS04"],"front":"Quyền hạn trên tài sản người khác — nêu ý nghĩa và áp dụng?","back":"Manager/analyst ảnh hưởng đến hưu trí, tiết kiệm và mục tiêu tài chính của khách hàng. Khách hàng chấp nhận ủy quyền trong điều kiện không thể giám sát mọi quyết định; vì thế cần tiêu chuẩn trung thực, năng lực và thận trọng cao."},{"id":"C04-02","los_ids":["CFA26-10-01-LOS04"],"front":"Rủi ro hệ thống và ngoại tác — nêu ý nghĩa và áp dụng?","back":"Thông tin sai hoặc thao túng giá có thể làm méo allocation of capital, giảm liquidity và độ tin cậy của benchmarks. Tác động đạo đức không chỉ là P&L của một nhà đầu tư, mà còn ảnh hưởng cơ chế vận hành thị trường."},{"id":"C04-03","los_ids":["CFA26-10-01-LOS04"],"front":"Xung đột kinh tế — nêu ý nghĩa và áp dụng?","back":"Research analysts, brokers, wealth managers và sales teams có động cơ phí/bonus tạo khác biệt với mục tiêu khách hàng. Cơ chế tránh/tiết lộ xung đột và kiểm soát disclosure làm giảm rủi ro tự lợi."},{"id":"C05-01","los_ids":["CFA26-10-01-LOS05"],"front":"Professionalism khác job title — nêu ý nghĩa và áp dụng?","back":"Professionalism thể hiện competence, diligence, independence, integrity và accountability trong mọi công việc chuyên môn. Danh thiếp ghi “senior analyst” không thay thế năng lực phân tích và hành vi có trách nhiệm."},{"id":"C05-02","los_ids":["CFA26-10-01-LOS05"],"front":"Fiduciary versus suitability — nêu ý nghĩa và áp dụng?","back":"Fiduciary standard đòi hỏi quản lý tài sản cho lợi ích khách hàng, thận trọng và loyal. Suitability standard nhấn mạnh sản phẩm/khuyến nghị phù hợp mục tiêu/ràng buộc của khách hàng. Hai chuẩn này có phạm vi nghĩa vụ khác nhau; không được giả định phù hợp là đã tối ưu lợi ích."},{"id":"C05-03","los_ids":["CFA26-10-01-LOS05"],"front":"Professional judgment — nêu ý nghĩa và áp dụng?","back":"Independent judgment đòi hỏi sử dụng bằng chứng khách quan, tránh áp lực deal fees và không biến ý kiến thành fact. Khi thông tin chưa đầy đủ, phải công bố assumptions, uncertainties và giới hạn của quy trình."},{"id":"C06-01","los_ids":["CFA26-10-01-LOS06"],"front":"Overconfidence về đạo đức cá nhân — nêu ý nghĩa và áp dụng?","back":"Người hành nghề có thể tin mình luôn trung thực và bỏ qua nguy cơ bị ảnh hưởng bởi incentives, peers hoặc authority. Self-perception tốt không phải bằng chứng rằng quyết định trong pressure sẽ khách quan."},{"id":"C06-02","los_ids":["CFA26-10-01-LOS06"],"front":"Situational influences — nêu ý nghĩa và áp dụng?","back":"Áp lực chỉ tiêu, loyalty với nhóm, người quản lý có quyền thưởng/phạt và normalization of deviance khiến người giỏi cũng hành động sai. Nhận diện structural pressures trước khi có dilemma là cách phòng ngừa hiệu quả."},{"id":"C06-03","los_ids":["CFA26-10-01-LOS06"],"front":"Compliance-only mindset — nêu ý nghĩa và áp dụng?","back":"Thực hiện đúng minimum rules nhưng bỏ qua spirit of ethics có thể dẫn đến marketing misleading hoặc cấu trúc giao dịch trốn tránh trách nhiệm. Checklist pháp lý hữu ích nhưng không thay được ethical reasoning về consequences."},{"id":"C07-01","los_ids":["CFA26-10-01-LOS07"],"front":"Ethical không đồng nhất legal — nêu ý nghĩa và áp dụng?","back":"Law xác lập yêu cầu pháp lý có enforcement của cơ quan chức năng; ethics là tập hợp nguyên tắc hành vi có thể đặt chuẩn cao hơn luật. Một hành vi được luật cho phép chưa chắc công bằng, trung thực hoặc đáp ứng nghĩa vụ đối với khách hàng."},{"id":"C07-02","los_ids":["CFA26-10-01-LOS07"],"front":"Bốn góc phần tư hành vi — nêu ý nghĩa và áp dụng?","back":"Có thể legal+ethical, legal+unethical, illegal+unethical và thậm chí illegal nhưng có mục đích đạo đức trong một số bối cảnh. Trong chuẩn CFA, khi conflict giữa applicable laws/rules và Code/Standards, thành viên phải tuân thủ quy định nghiêm ngặt hơn; không được tự biện hộ vi phạm luật vì mục đích đạo đức."},{"id":"C07-03","los_ids":["CFA26-10-01-LOS07"],"front":"Khác biệt phạm vi áp dụng — nêu ý nghĩa và áp dụng?","back":"Laws thay đổi theo jurisdiction và đôi khi chậm hơn innovation; professional standards có thể đặt common obligations xuyên biên giới. Ethical standards không bỏ qua local legal duties, và tuân thủ luật không tự động là đủ nếu Code nghiêm hơn."},{"id":"C08-01","los_ids":["CFA26-10-01-LOS08"],"front":"Xác định facts và dilemma — nêu ý nghĩa và áp dụng?","back":"Bắt đầu từ sự kiện có căn cứ, rủi ro, phạm vi quyết định và các bên liên quan. Phân biệt fact, opinion và chưa biết; tránh framing sai khiến giải pháp nghiêng về mục tiêu doanh số ngay từ đầu."},{"id":"C08-02","los_ids":["CFA26-10-01-LOS08"],"front":"Nhận diện duties, stakeholders và situational influence — nêu ý nghĩa và áp dụng?","back":"Liệt kê clients/employer/colleagues/market, duties tương ứng, conflicts, incentives và điểm mù của bản thân. Một quyết định có thể có nhiều bên bị tác động, không nên chỉ hỏi người trả tiền có hài lòng hay không."},{"id":"C08-03","los_ids":["CFA26-10-01-LOS08"],"front":"Xây dựng và đánh giá alternatives — nêu ý nghĩa và áp dụng?","back":"Đối chiếu phương án với laws, Code/Standards và consequences ngắn-dài hạn; tính đến reputational, market trust và fairness. Tham vấn peers/compliance khi phù hợp, cân nhắc cách diễn giải với stakeholder độc lập."}],"review_status":"targeted_los_source_scenario_and_browser_QA_pass_not_exhaustive_all_PDFs"},{"module_id":"CFA26-10-02","title":"Code of Ethics and Standards of Professional Conduct","version":"2026","source_basis":[{"source_id":"CFAI_2026","pdf_pages":[47,64],"relation":"primary"},{"source_id":"Kaplan_2026","pdf_pages":[161,166],"relation":"supplementary"},{"source_id":"SAPP_2026","pdf_pages":[16,22],"relation":"supplementary"}],"los_coverage":[{"los_id":"CFA26-10-02-LOS01","learning_goal_vi":"Mô tả cấu trúc Professional Conduct Program và cơ chế thực thi Code/Standards.","status":"targeted_CFAI_Kaplan_SAPP_and_scenario_QA_pass","competency_criteria":["Phù hợp động từ và LOS CFAI 2026","Đối chiếu với Kaplan/SAPP cùng chủ đề","Có 4+ phần lý thuyết tiếng Việt và 2 ví dụ tình huống","3 câu hỏi tự biên soạn có giải thích lựa chọn"],"concept_ids":["S01-01","S01-02","S01-03","S01-04"],"formula_ids":["F01-01"],"example_ids":["E01-01","E01-02"],"question_ids":["Q01-01","Q01-02","Q01-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":48},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":161},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":17}},"missing_items":[]},{"los_id":"CFA26-10-02-LOS02","learning_goal_vi":"Xác định sáu thành phần Code of Ethics và bảy Standards of Professional Conduct.","status":"targeted_CFAI_Kaplan_SAPP_and_scenario_QA_pass","competency_criteria":["Phù hợp động từ và LOS CFAI 2026","Đối chiếu với Kaplan/SAPP cùng chủ đề","Có 4+ phần lý thuyết tiếng Việt và 2 ví dụ tình huống","3 câu hỏi tự biên soạn có giải thích lựa chọn"],"concept_ids":["S02-01","S02-02","S02-03","S02-04"],"formula_ids":["F02-01"],"example_ids":["E02-01","E02-02"],"question_ids":["Q02-01","Q02-02","Q02-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":58},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":162},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":19}},"missing_items":[]},{"los_id":"CFA26-10-02-LOS03","learning_goal_vi":"Giải thích trách nhiệm đạo đức theo Code và toàn bộ các tiểu chuẩn I–VII.","status":"targeted_CFAI_Kaplan_SAPP_and_scenario_QA_pass","competency_criteria":["Phù hợp động từ và LOS CFAI 2026","Đối chiếu với Kaplan/SAPP cùng chủ đề","Có 4+ phần lý thuyết tiếng Việt và 2 ví dụ tình huống","3 câu hỏi tự biên soạn có giải thích lựa chọn"],"concept_ids":["S03-01","S03-02","S03-03","S03-04","S03-05","S03-06","S03-07","S03-08"],"formula_ids":["F03-01"],"example_ids":["E03-01","E03-02"],"question_ids":["Q03-01","Q03-02","Q03-03"],"source_anchor_pages":{"CFAI_2026":{"file":"2026_CFA_L1V10_Ethics_ONLINE.pdf","pdf_page":59},"Kaplan_2026":{"file":"Kaplan SchweserNotes Book4.pdf","pdf_page":162},"SAPP_2026":{"file":"SAPP Ethics.pdf","pdf_page":20}},"missing_items":[]}],"sections":[{"id":"S01-01","los_ids":["CFA26-10-02-LOS01"],"heading_vi":"Professional Conduct Program và jurisdiction","body_vi":"CFA Institute Professional Conduct Program (PCP) tổ chức điều tra và xử lý vấn đề professional conduct đối với members/candidates. Đây là quy trình kỷ luật nghề nghiệp, không thay thế cơ quan tòa án hoặc cơ quan giám sát thị trường."},{"id":"S01-02","los_ids":["CFA26-10-02-LOS01"],"heading_vi":"Các nguồn khởi xướng điều tra","body_vi":"Thông tin có thể đến từ self-disclosure, written complaints, media/public sources hoặc phản ánh khác. Staff có thể yêu cầu giải trình bằng văn bản, phỏng vấn, thu thập tài liệu và xác minh hành vi trước khi khuyến nghị giải quyết."},{"id":"S01-03","los_ids":["CFA26-10-02-LOS01"],"heading_vi":"Xử lý và quyền phản hồi","body_vi":"Tùy facts, vấn đề có thể được giải quyết mà không cần hearing hoặc cần trình hội đồng. Người bị xem xét có cơ hội phản hồi theo quy trình, decision có thể dẫn đến public censure, suspension hoặc revocation như phù hợp; không phải mọi complaint đều lập tức thành violation."},{"id":"S01-04","los_ids":["CFA26-10-02-LOS01"],"heading_vi":"Professional standards governance","body_vi":"Standards of Practice Council góp phần duy trì và giải thích Code/Standards, trong khi professional conduct enforcement xem xét trường hợp cụ thể. Không nhầm chức năng thiết lập quy tắc với adjudication hành vi cá nhân."},{"id":"S02-01","los_ids":["CFA26-10-02-LOS02"],"heading_vi":"Sáu nguyên tắc Code – nhóm 1","body_vi":"Sáu nội dung cốt lõi: hành động với integrity, competence, diligence, respect và ethics; đặt integrity của profession và lợi ích client trên lợi ích cá nhân; dùng reasonable care cùng independent professional judgment trong investment activities."},{"id":"S02-02","los_ids":["CFA26-10-02-LOS02"],"heading_vi":"Sáu nguyên tắc Code – nhóm 2","body_vi":"Ba nội dung còn lại: thực hành và khuyến khích hành vi chuyên nghiệp/đạo đức; thúc đẩy integrity và viability của global capital markets vì lợi ích xã hội; duy trì và cải thiện professional competence của bản thân và của profession."},{"id":"S02-03","los_ids":["CFA26-10-02-LOS02"],"heading_vi":"Bảy nhóm Standards I–IV","body_vi":"I Professionalism, II Integrity of Capital Markets, III Duties to Clients, IV Duties to Employers. Không nhầm III loyalty với IV loyalty: III đặt client interest trước, IV bảo vệ employer trong employment duties theo luật/Code."},{"id":"S02-04","los_ids":["CFA26-10-02-LOS02"],"heading_vi":"Bảy nhóm Standards V–VII","body_vi":"V Investment Analysis, Recommendations, and Actions; VI Conflicts of Interest; VII Responsibilities as a CFA Institute Member or CFA Candidate. Module 3 sẽ đi sâu các tiểu chuẩn; không xem bộ rules như list names để học thuộc mà thiếu khả năng áp dụng."},{"id":"S03-01","los_ids":["CFA26-10-02-LOS03"],"heading_vi":"I — Professionalism: năm tiểu chuẩn","body_vi":"I(A) Knowledge of the Law: tuân chuẩn nghiêm hơn và dissociate from violations; I(B) Independence and Objectivity: chống undue influence, gifts; I(C) Misrepresentation: cấm knowingly misleading analysis; I(D) Misconduct: tránh dishonesty/fraud; I(E) Competence: hành động và duy trì năng lực cần thiết. I(E) không bắt buộc một khóa CME cụ thể."},{"id":"S03-02","los_ids":["CFA26-10-02-LOS03"],"heading_vi":"II — Integrity of Capital Markets","body_vi":"II(A) Material Nonpublic Information: không giao dịch hoặc khiến người khác giao dịch trên thông tin quan trọng chưa công khai; II(B) Market Manipulation: cấm làm sai lệch giá/khối lượng với mục tiêu gây hiểu nhầm. Mosaic theory có thể chấp nhận khi kết luận dựa trên public + nonmaterial nonpublic info và nghiên cứu hợp lý."},{"id":"S03-03","los_ids":["CFA26-10-02-LOS03"],"heading_vi":"III — Duties to Clients","body_vi":"III(A) Loyalty, Prudence, and Care: đặt clients trước; III(B) Fair Dealing: đối xử công bằng chứ không nhất thiết cùng thời điểm tuyệt đối; III(C) Suitability: phân tích client objectives/constraints và portfolio context; III(D) Performance Presentation: công bằng, chính xác, đầy đủ; III(E) Preservation of Confidentiality: bảo mật ngoại trừ illegal activities, disclosure required by law, hoặc client consent."},{"id":"S03-04","los_ids":["CFA26-10-02-LOS03"],"heading_vi":"IV — Duties to Employers","body_vi":"IV(A) Loyalty: không làm hại employer/chiếm đoạt bí mật; IV(B) Additional Compensation Arrangements: written consent của mọi bên liên quan trước khi nhận benefit competing/conflicting; IV(C) Responsibilities of Supervisors: có reasonable procedures, giám sát nhằm phát hiện/phòng tránh violations và corrective actions."},{"id":"S03-05","los_ids":["CFA26-10-02-LOS03"],"heading_vi":"V — Investment Analysis, Recommendations, and Actions","body_vi":"V(A) Diligence and Reasonable Basis: nghiên cứu đủ cơ sở; V(B) Communication with Clients: nêu bản chất dịch vụ, chi phí, phương pháp, risks/limitations, material process changes, phân biệt facts/opinions; V(C) Record Retention: giữ hồ sơ cho research và recommendations. V(B) bản mới nhấn mạnh disclosure of services and costs."},{"id":"S03-06","los_ids":["CFA26-10-02-LOS03"],"heading_vi":"VI — Conflicts of Interest","body_vi":"VI(A) Avoid or Disclose Conflicts: ưu tiên tránh conflict, nếu không thể phải disclosure đầy đủ/công bằng/hiển thị rõ và dễ hiểu; VI(B) Priority of Transactions: client và employer transactions trước personal beneficial ownership; VI(C) Referral Fees: disclose to employer, clients và prospects khi phù hợp."},{"id":"S03-07","los_ids":["CFA26-10-02-LOS03"],"heading_vi":"VII — CFA Membership and Candidacy","body_vi":"VII(A) Conduct as Participants in CFA Institute Programs: bảo vệ integrity, exam security và program reputation; VII(B) Reference to CFA Institute, CFA designation, and Program: không thổi phồng thành tích, diễn đạt sai benefits hay quyền của charter/candidacy. “CFA Level I” không phải danh hiệu chuyên môn đã được cấp."},{"id":"S03-08","los_ids":["CFA26-10-02-LOS03"],"heading_vi":"Phương pháp xác định nhiều Standards cùng lúc","body_vi":"Một tình huống có thể vi phạm đồng thời II(A), III(A), V(B) và VI(A). Hãy tách actors, facts, duties, recipient, timing, conflicts và required action; không dùng một nhãn Standard để che bỏ vi phạm khác. Cần chọn best action theo facts, không “chọn từ khóa” máy móc."}],"formulae":[{"id":"F01-01","los_ids":["CFA26-10-02-LOS01"],"expression":"Ethical review checklist: Facts → Stakeholders → Duties and Standards → Alternatives → Decision → Review","variables":["Mô hình ra quyết định mô tả, không phải công thức toán học trong CFA Institute Curriculum."],"assumptions":["Quy trình lặp lại khi có thông tin mới; không thay thế việc áp dụng Standards cụ thể."]},{"id":"F02-01","los_ids":["CFA26-10-02-LOS02"],"expression":"Ethical review checklist: Facts → Stakeholders → Duties and Standards → Alternatives → Decision → Review","variables":["Mô hình ra quyết định mô tả, không phải công thức toán học trong CFA Institute Curriculum."],"assumptions":["Quy trình lặp lại khi có thông tin mới; không thay thế việc áp dụng Standards cụ thể."]},{"id":"F03-01","los_ids":["CFA26-10-02-LOS03"],"expression":"Ethical review checklist: Facts → Stakeholders → Duties and Standards → Alternatives → Decision → Review","variables":["Mô hình ra quyết định mô tả, không phải công thức toán học trong CFA Institute Curriculum."],"assumptions":["Quy trình lặp lại khi có thông tin mới; không thay thế việc áp dụng Standards cụ thể."]}],"worked_examples":[{"id":"E01-01","los_ids":["CFA26-10-02-LOS01"],"problem":"Tin truyền thông cho rằng manager làm giả lịch sử lợi suất.","solution_steps":["PCP có thể xem xét thông tin media và yêu cầu written explanation, performance records.","Chưa có dữ kiện đủ thì không kết luận violation; investigation xác minh facts."],"answer":"Media reporting có thể là nguồn của inquiry, không bắt buộc phải có complaint từ client."},{"id":"E01-02","los_ids":["CFA26-10-02-LOS01"],"problem":"CFA candidate bị yêu cầu cung cấp records trong vụ suspected conflicts.","solution_steps":["Candidate có nghĩa vụ hợp tác theo quy trình liên quan và giải thích bằng tài liệu.","Nếu investigation tìm thấy evidence, có thể tiến hành disciplinary action; không mặc định mọi vụ phải hearing."],"answer":"PCP không đồng nghĩa criminal prosecution hay chỉ một hình thức xử phạt."},{"id":"E02-01","los_ids":["CFA26-10-02-LOS02"],"problem":"Adviser nói: “Code chỉ yêu cầu tránh gian lận, không đề cập nâng cao năng lực”.","solution_steps":["Code cũng yêu cầu maintain/improve professional competence.","Cần phân biệt aspirational Code và explicit Standard I(E) Competence; cả hai tồn tại."],"answer":"Tuyên bố bỏ qua competence không chính xác."},{"id":"E02-02","los_ids":["CFA26-10-02-LOS02"],"problem":"Một nhân viên giữ kín thông tin khách hàng nhưng lại quảng bá tỷ suất hoàn toàn sai.","solution_steps":["Confidentiality là Standard III(E), performance presentation là III(D).","Việc đáp ứng một standard không xóa violation standard khác."],"answer":"Cần rà soát theo các nhóm Standards liên quan, không đánh đồng tất cả thành honesty chung chung."},{"id":"E03-01","los_ids":["CFA26-10-02-LOS03"],"problem":"Analyst nhận stock bonus từ issuer, không disclosure, rồi khuyến nghị mua.","solution_steps":["Có thể vi phạm I(B) objectivity, VI(A) conflicts và V(A) nếu recommendation thiếu research.","Tiết lộ prominent, cân nhắc từ chối coverage nếu conflict không kiểm soát; báo cáo khách quan."],"answer":"Một giao dịch có thể liên quan nhiều Standard; disclosure không bảo đảm mọi conflict đều chấp nhận."},{"id":"E03-02","los_ids":["CFA26-10-02-LOS03"],"problem":"Employee thực hiện personal trade trước order của client và không disclose referral fee.","solution_steps":["Personal trade trước client order liên quan VI(B). Referral fee không disclose liên quan VI(C).","Cần client/employer priority, disclosure và compliance policies."],"answer":"Kết luận không chỉ là “thiếu trung thực”, phải xác định nghĩa vụ theo từng subsection."}],"questions":[{"id":"Q01-01","los_ids":["CFA26-10-02-LOS01"],"stem":"Nguồn nào có thể khởi xướng PCP inquiry?","options":["Chỉ báo cáo nội bộ của công ty","Chỉ tòa án","Media/public information"],"correct_option":2,"explanation":"PCP có thể xem xét complaints, media, self-disclosure và các nguồn khác; không giới hạn ở văn bản từ tòa án."},{"id":"Q01-02","los_ids":["CFA26-10-02-LOS01"],"stem":"Mọi investigation bắt buộc hearing?","options":["Không; tùy facts và resolution","Có, không có ngoại lệ","Chỉ cần media report là xử phạt"],"correct_option":0,"explanation":"Professional conduct reviews có nhiều bước và kết quả; không phải mỗi allegation chắc chắn dẫn đến hearing/violation."},{"id":"Q01-03","los_ids":["CFA26-10-02-LOS01"],"stem":"PCP là?","options":["Một exchange settlement system","Hệ thống thực thi Code/Standards nghề nghiệp của CFA Institute","Toàn bộ luật hình sự"],"correct_option":1,"explanation":"Professional Conduct Program là cơ chế điều tra và xử lý kỷ luật nghề nghiệp, tách biệt legal enforcement của cơ quan nhà nước."},{"id":"Q02-01","los_ids":["CFA26-10-02-LOS02"],"stem":"Standard II nói về?","options":["Employer loyalty","Designation references","Market integrity"],"correct_option":2,"explanation":"II gồm material nonpublic information và market manipulation, nhằm giữ tính toàn vẹn của capital markets."},{"id":"Q02-02","los_ids":["CFA26-10-02-LOS02"],"stem":"Có bao nhiêu nhóm Standards?","options":["Bảy","Tám","Sáu"],"correct_option":0,"explanation":"CFA Institute Standards of Professional Conduct được chia thành bảy nhóm I–VII, với các tiểu chuẩn riêng."},{"id":"Q02-03","los_ids":["CFA26-10-02-LOS02"],"stem":"Code of Ethics yêu cầu điều nào sau đây?","options":["Luôn bảo đảm alpha dương","Duy trì và cải thiện competence của bản thân và đồng nghiệp","Chỉ học một lần trước thi"],"correct_option":1,"explanation":"Một trong sáu nguyên tắc Code yêu cầu chuyên môn được duy trì, phát triển, đồng thời thúc đẩy năng lực của nghề nghiệp."},{"id":"Q03-01","los_ids":["CFA26-10-02-LOS03"],"stem":"Đâu là yêu cầu mới trong Standard I(E)?","options":["Được phép nhận tiền để thao túng market","Mọi member bắt buộc học 30 giờ/năm","Duy trì competence cần thiết cho professional responsibilities"],"correct_option":2,"explanation":"I(E) Competence yêu cầu có và duy trì năng lực phù hợp với nhiệm vụ cụ thể, không bắt buộc một chương trình CE cố định cho mọi member."},{"id":"Q03-02","los_ids":["CFA26-10-02-LOS03"],"stem":"Khi unavoidable conflict of interest xảy ra, VI(A) ưu tiên?","options":["Avoid hoặc full and fair prominent disclosure","Ẩn xung đột","Báo chỉ cho bạn bè"],"correct_option":0,"explanation":"VI(A) Avoid or Disclose Conflicts yêu cầu tránh xung đột hoặc công bố đầy đủ/công bằng bằng ngôn ngữ dễ hiểu và vị trí rõ ràng."},{"id":"Q03-03","los_ids":["CFA26-10-02-LOS03"],"stem":"Member gửi client recommendation mà không giải thích chi phí của dịch vụ?","options":["Không phải nội dung Code 2026","Có thể vi phạm V(B) Communication","Chỉ vi phạm VII(A)"],"correct_option":1,"explanation":"Standard V(B) trong bản hiện hành yêu cầu disclosure nature of services và associated client costs, bên cạnh methods, limitations và fact/opinion distinction."}],"flashcards":[{"id":"C01-01","los_ids":["CFA26-10-02-LOS01"],"front":"Professional Conduct Program và jurisdiction — nêu ý nghĩa và áp dụng?","back":"CFA Institute Professional Conduct Program (PCP) tổ chức điều tra và xử lý vấn đề professional conduct đối với members/candidates. Đây là quy trình kỷ luật nghề nghiệp, không thay thế cơ quan tòa án hoặc cơ quan giám sát thị trường."},{"id":"C01-02","los_ids":["CFA26-10-02-LOS01"],"front":"Các nguồn khởi xướng điều tra — nêu ý nghĩa và áp dụng?","back":"Thông tin có thể đến từ self-disclosure, written complaints, media/public sources hoặc phản ánh khác. Staff có thể yêu cầu giải trình bằng văn bản, phỏng vấn, thu thập tài liệu và xác minh hành vi trước khi khuyến nghị giải quyết."},{"id":"C01-03","los_ids":["CFA26-10-02-LOS01"],"front":"Xử lý và quyền phản hồi — nêu ý nghĩa và áp dụng?","back":"Tùy facts, vấn đề có thể được giải quyết mà không cần hearing hoặc cần trình hội đồng. Người bị xem xét có cơ hội phản hồi theo quy trình, decision có thể dẫn đến public censure, suspension hoặc revocation như phù hợp; không phải mọi complaint đều lập tức thành violation."},{"id":"C02-01","los_ids":["CFA26-10-02-LOS02"],"front":"Sáu nguyên tắc Code – nhóm 1 — nêu ý nghĩa và áp dụng?","back":"Sáu nội dung cốt lõi: hành động với integrity, competence, diligence, respect và ethics; đặt integrity của profession và lợi ích client trên lợi ích cá nhân; dùng reasonable care cùng independent professional judgment trong investment activities."},{"id":"C02-02","los_ids":["CFA26-10-02-LOS02"],"front":"Sáu nguyên tắc Code – nhóm 2 — nêu ý nghĩa và áp dụng?","back":"Ba nội dung còn lại: thực hành và khuyến khích hành vi chuyên nghiệp/đạo đức; thúc đẩy integrity và viability của global capital markets vì lợi ích xã hội; duy trì và cải thiện professional competence của bản thân và của profession."},{"id":"C02-03","los_ids":["CFA26-10-02-LOS02"],"front":"Bảy nhóm Standards I–IV — nêu ý nghĩa và áp dụng?","back":"I Professionalism, II Integrity of Capital Markets, III Duties to Clients, IV Duties to Employers. Không nhầm III loyalty với IV loyalty: III đặt client interest trước, IV bảo vệ employer trong employment duties theo luật/Code."},{"id":"C03-01","los_ids":["CFA26-10-02-LOS03"],"front":"I — Professionalism: năm tiểu chuẩn — nêu ý nghĩa và áp dụng?","back":"I(A) Knowledge of the Law: tuân chuẩn nghiêm hơn và dissociate from violations; I(B) Independence and Objectivity: chống undue influence, gifts; I(C) Misrepresentation: cấm knowingly misleading analysis; I(D) Misconduct: tránh dishonesty/fraud; I(E) Competence: hành động và duy trì năng lực cần thiết. I(E) không bắt buộc một khóa CME cụ thể."},{"id":"C03-02","los_ids":["CFA26-10-02-LOS03"],"front":"II — Integrity of Capital Markets — nêu ý nghĩa và áp dụng?","back":"II(A) Material Nonpublic Information: không giao dịch hoặc khiến người khác giao dịch trên thông tin quan trọng chưa công khai; II(B) Market Manipulation: cấm làm sai lệch giá/khối lượng với mục tiêu gây hiểu nhầm. Mosaic theory có thể chấp nhận khi kết luận dựa trên public + nonmaterial nonpublic info và nghiên cứu hợp lý."},{"id":"C03-03","los_ids":["CFA26-10-02-LOS03"],"front":"III — Duties to Clients — nêu ý nghĩa và áp dụng?","back":"III(A) Loyalty, Prudence, and Care: đặt clients trước; III(B) Fair Dealing: đối xử công bằng chứ không nhất thiết cùng thời điểm tuyệt đối; III(C) Suitability: phân tích client objectives/constraints và portfolio context; III(D) Performance Presentation: công bằng, chính xác, đầy đủ; III(E) Preservation of Confidentiality: bảo mật ngoại trừ illegal activities, disclosure required by law, hoặc client consent."}],"review_status":"targeted_los_source_scenario_and_browser_QA_pass_not_exhaustive_all_PDFs"}]);
